-- DailyTest: Mathematics import (50 MCQs).
-- Generated from content/mathematics/arithmetic-number-systems.json (validated + deduped). Idempotent.

insert into public.books (title) values ('Mathematics') on conflict (title) do nothing;

insert into public.categories (book_id, name)
select id, 'Arithmetic & Number Systems' from public.books where title = 'Mathematics'
on conflict (book_id, name) do nothing;

insert into public.mcqs (book_id, category_id, question_en, question_ur, options,
  correct_text, explanation, source_ref, difficulty, level, review_status)
select b.id, c.id, v.question_en, nullif(v.question_ur, ''), v.options::jsonb,
  v.correct_text, v.explanation, v.source_ref, v.difficulty, v.level, v.review_status
from public.books b join public.categories c on c.book_id = b.id
join (values
  ('Arithmetic & Number Systems', 'What is 12% of 250?', '250 کا 12 فیصد کیا ہے؟', '{"A":"25","B":"30","C":"32","D":"28"}', '30', '12 × 250 ÷ 100 = 30.', 'math-001', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the average of 5, 15, 25 and 35?', '5، 15، 25 اور 35 کا اوسط کیا ہے؟', '{"A":"18","B":"25","C":"20","D":"22"}', '20', '(5 + 15 + 25 + 35) ÷ 4 = 80 ÷ 4 = 20.', 'math-002', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A rectangle is 12 cm long and 7 cm wide. What is its area?', 'ایک مستطیل 12 سینٹی میٹر لمبی اور 7 سینٹی میٹر چوڑی ہے۔ اس کا رقبہ کیا ہے؟', '{"A":"38 sq cm","B":"76 sq cm","C":"96 sq cm","D":"84 sq cm"}', '84 sq cm', 'Area = length × width = 12 × 7 = 84 sq cm.', 'math-003', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the square root of 169?', '169 کا جذر المربع کیا ہے؟', '{"A":"13","B":"14","C":"17","D":"12"}', '13', '13 × 13 = 169, so the square root of 169 is 13.', 'math-004', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the supplementary angle of 65 degrees?', '180 درجے میں سے 65 درجے کا زاویہ نکالنے پر کتنا زاویہ بچتا ہے؟', '{"A":"25°","B":"115°","C":"125°","D":"105°"}', '115°', 'Supplementary angles add to 180°, so 180° − 65° = 115°.', 'math-005', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Solve for x: 3x + 9 = 30', 'اگر 3x + 9 = 30 ہو تو x کی قیمت کیا ہے؟', '{"A":"5","B":"9","C":"7","D":"8"}', '7', '3x = 30 − 9 = 21, so x = 7.', 'math-006', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is 2/5 expressed as a percentage?', '2/5 کو فیصد میں لکھیں۔', '{"A":"25%","B":"52%","C":"20%","D":"40%"}', '40%', '2 ÷ 5 × 100 = 40%.', 'math-007', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Which is the smallest odd composite number?', 'سب سے چھوٹا طاق مرکب عدد کون سا ہے؟', '{"A":"9","B":"15","C":"21","D":"1"}', '9', '9 = 3 × 3 is the smallest odd number with factors besides 1 and itself; 1 is neither prime nor composite.', 'math-008', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is 30% of 90?', '90 کا 30 فیصد کیا ہے؟', '{"A":"24","B":"27","C":"30","D":"21"}', '27', '30 × 90 ÷ 100 = 27.', 'math-009', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'If 6 chairs cost Rs 7,200, what is the cost of 4 chairs?', 'اگر 6 کرسیوں کی قیمت 7200 روپے ہو تو 4 کرسیوں کی قیمت کیا ہوگی؟', '{"A":"Rs 4,200","B":"Rs 5,400","C":"Rs 4,800","D":"Rs 4,500"}', 'Rs 4,800', 'One chair costs 7200 ÷ 6 = Rs 1,200, so 4 chairs cost Rs 4,800.', 'math-010', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the perimeter of a rectangle 9 cm long and 4 cm wide?', '9 سینٹی میٹر لمبی اور 4 سینٹی میٹر چوڑی مستطیل کا احاطہ کیا ہے؟', '{"A":"36 cm","B":"13 cm","C":"32 cm","D":"26 cm"}', '26 cm', 'Perimeter = 2 × (9 + 4) = 26 cm.', 'math-011', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the value of 4 to the power 3 (4^3)?', '4 کی قوت 3 (4^3) کی قیمت کیا ہے؟', '{"A":"64","B":"48","C":"16","D":"12"}', '64', '4 × 4 × 4 = 64.', 'math-012', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the LCM of 6 and 8?', '6 اور 8 کا ذواضعاف اقل (LCM) کیا ہے؟', '{"A":"16","B":"24","C":"48","D":"12"}', '24', 'Multiples of 6: 6, 12, 18, 24; of 8: 8, 16, 24. The first common one is 24.', 'math-013', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the HCF of 15 and 25?', '15 اور 25 کا عاد اعظم (HCF) کیا ہے؟', '{"A":"15","B":"25","C":"5","D":"3"}', '5', 'Common factors of 15 and 25 are 1 and 5; the greatest is 5.', 'math-014', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Convert 0.25 into a fraction.', '0.25 کو کسر میں لکھیں۔', '{"A":"1/2","B":"2/5","C":"1/5","D":"1/4"}', '1/4', '0.25 = 25/100 = 1/4.', 'math-015', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is 20% of 650?', '650 کا 20 فیصد کیا ہے؟', '{"A":"130","B":"120","C":"140","D":"150"}', '130', '20% is one fifth, and 650 ÷ 5 = 130.', 'math-016', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A van travels at 80 km/h for 2.5 hours. How far does it go?', 'ایک گاڑی 80 کلومیٹر فی گھنٹہ کی رفتار سے 2.5 گھنٹے چلے تو کتنا فاصلہ طے کرے گی؟', '{"A":"160 km","B":"200 km","C":"240 km","D":"180 km"}', '200 km', 'Distance = speed × time = 80 × 2.5 = 200 km.', 'math-017', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the ratio of 36 to 48 in simplest form?', '36 اور 48 کی نسبت سادہ ترین شکل میں کیا ہے؟', '{"A":"9:12","B":"4:3","C":"3:4","D":"6:8"}', '3:4', 'Divide both sides by 12: 36 ÷ 12 = 3 and 48 ÷ 12 = 4.', 'math-018', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is 75% of 400?', '400 کا 75 فیصد کیا ہے؟', '{"A":"250","B":"350","C":"275","D":"300"}', '300', '75% is three quarters, and 3 × 400 ÷ 4 = 300.', 'math-019', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Solve for y: 4y − 12 = 20', 'اگر 4y − 12 = 20 ہو تو y کی قیمت کیا ہے؟', '{"A":"8","B":"6","C":"7","D":"10"}', '8', '4y = 20 + 12 = 32, so y = 8.', 'math-020', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the square of 12?', '12 کا مربع کیا ہے؟', '{"A":"124","B":"144","C":"142","D":"169"}', '144', '12 × 12 = 144.', 'math-021', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the cube root of 64?', '64 کا جذر المکعب کیا ہے؟', '{"A":"8","B":"6","C":"4","D":"16"}', '4', '4 × 4 × 4 = 64, so the cube root of 64 is 4.', 'math-022', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the median of 2, 6, 9, 12 and 17?', '2، 6، 9، 12 اور 17 کا وسطانیہ (median) کیا ہے؟', '{"A":"6","B":"12","C":"8","D":"9"}', '9', 'The numbers are already ordered; the middle of five values is 9.', 'math-023', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Which number appears most often in 3, 7, 7, 9, 11, 7 and 5?', '3، 7، 7، 9، 11، 7 اور 5 میں سب سے زیادہ بار آنے والا عدد کون سا ہے؟', '{"A":"7","B":"3","C":"9","D":"11"}', '7', '7 appears three times, more than any other number.', 'math-024', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is 2000 − 875?', '2000 میں سے 875 نکالیں۔', '{"A":"1,225","B":"1,125","C":"1,025","D":"1,175"}', '1,125', '2000 − 875 = 1125.', 'math-025', 'easy', 'basic', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A number increased by 20% becomes 180. What is the number?', 'ایک عدد میں 20 فیصد اضافے سے 180 بنتا ہے۔ اصل عدد کیا ہے؟', '{"A":"144","B":"160","C":"150","D":"156"}', '150', 'The number × 1.2 = 180, so it is 180 ÷ 1.2 = 150.', 'math-026', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the average of the first 10 even numbers?', 'پہلے 10 جفت اعداد کا اوسط کیا ہے؟', '{"A":"10","B":"12","C":"9","D":"11"}', '11', 'They run 2 to 20, so the average is (2 + 20) ÷ 2 = 11.', 'math-027', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the LCM of 9, 12 and 15?', '9، 12 اور 15 کا ذواضعاف اقل (LCM) کیا ہے؟', '{"A":"180","B":"90","C":"120","D":"360"}', '180', '9 = 3², 12 = 2² × 3, 15 = 3 × 5, so LCM = 2² × 3² × 5 = 180.', 'math-028', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A train runs at 72 km/h. What is its speed in metres per second?', 'ایک ٹرین 72 کلومیٹر فی گھنٹہ کی رفتار سے چلتی ہے۔ میٹر فی سیکنڈ میں رفتار کتنی ہوگی؟', '{"A":"18 m/s","B":"20 m/s","C":"22 m/s","D":"25 m/s"}', '20 m/s', 'Multiply by 5/18: 72 × 5 ÷ 18 = 20 m/s.', 'math-029', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the simple interest on Rs 5,000 at 8% per year for 3 years?', '5000 روپے پر 8 فیصد سالانہ کی شرح سے 3 سال کا سادہ سود کتنا ہوگا؟', '{"A":"Rs 1,000","B":"Rs 1,500","C":"Rs 1,200","D":"Rs 800"}', 'Rs 1,200', 'Interest = 5000 × 8 × 3 ÷ 100 = Rs 1,200.', 'math-030', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Rs 560 is divided in the ratio 3:4. What is the smaller share?', '560 روپے 3:4 کی نسبت سے تقسیم کریں۔ چھوٹا حصہ کتنا ہوگا؟', '{"A":"Rs 320","B":"Rs 280","C":"Rs 210","D":"Rs 240"}', 'Rs 240', '3 + 4 = 7 parts; the smaller share is 3 × 560 ÷ 7 = Rs 240.', 'math-031', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Ahmed finishes a job in 6 days and Bilal in 12 days. How long will they take together?', 'احمد ایک کام 6 دن میں اور بلال 12 دن میں کرتا ہے۔ دونوں مل کر کتنے دن میں کریں گے؟', '{"A":"4 days","B":"3 days","C":"6 days","D":"5 days"}', '4 days', 'Together they do 1/6 + 1/12 = 1/4 of the job daily, so 4 days.', 'math-032', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A father is three times as old as his son, and their ages add to 48. How old is the son?', 'باپ کی عمر بیٹے سے تین گنا ہے اور دونوں کی عمروں کا مجموعہ 48 سال ہے۔ بیٹے کی عمر کیا ہے؟', '{"A":"16 years","B":"12 years","C":"10 years","D":"14 years"}', '12 years', '3 + 1 = 4 parts make 48 years, so the son is 48 ÷ 4 = 12.', 'math-033', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'An item''s price fell from Rs 250 to Rs 200. What is the percentage decrease?', 'ایک چیز کی قیمت 250 سے گھٹ کر 200 روپے ہوگئی۔ کمی کا فیصد کیا ہے؟', '{"A":"25%","B":"50%","C":"20%","D":"15%"}', '20%', 'The drop is Rs 50 on Rs 250: 50 × 100 ÷ 250 = 20%.', 'math-034', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is 3/4 + 2/3?', '3/4 اور 2/3 کا مجموعہ کیا ہے؟', '{"A":"5/7","B":"5/12","C":"1","D":"17/12"}', '17/12', '3/4 + 2/3 = 9/12 + 8/12 = 17/12.', 'math-035', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'If x = 5 and y = 2, what is the value of 2x − 3y?', 'اگر x = 5 اور y = 2 ہو تو 2x − 3y کی قیمت کیا ہے؟', '{"A":"4","B":"16","C":"−4","D":"9"}', '4', '2 × 5 − 3 × 2 = 10 − 6 = 4.', 'math-036', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Two angles add up to 90° and differ by 20°. What is the larger angle?', 'دو زاویے مل کر 90 درجے بنتے ہیں اور ان میں 20 درجے کا فرق ہے۔ بڑا زاویہ کیا ہے؟', '{"A":"45°","B":"55°","C":"65°","D":"35°"}', '55°', 'They add to 90°, so the larger is (90 + 20) ÷ 2 = 55°.', 'math-037', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'What is the area of a circle with diameter 14 cm? (π = 22/7)', '14 سینٹی میٹر قطر والے دائرے کا رقبہ کیا ہے؟ (π = 22/7)', '{"A":"44 sq cm","B":"88 sq cm","C":"154 sq cm","D":"616 sq cm"}', '154 sq cm', 'Radius = 14 ÷ 2 = 7, so area = 22/7 × 7 × 7 = 154 sq cm.', 'math-038', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Six numbers average 15. Adding a seventh number, 29, what is the new average?', '6 اعداد کا اوسط 15 ہے۔ ساتواں عدد 29 شامل کرنے پر نیا اوسط کیا ہوگا؟', '{"A":"16","B":"19","C":"22","D":"17"}', '17', 'Total becomes 6 × 15 + 29 = 119, and 119 ÷ 7 = 17.', 'math-039', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A coat marked Rs 1,200 sells at 15% off. What is the sale price?', '1200 روپے والی چیز پر 15 فیصد رعایت کے بعد قیمت کیا ہوگی؟', '{"A":"Rs 1,020","B":"Rs 1,050","C":"Rs 980","D":"Rs 1,185"}', 'Rs 1,020', 'Discount = 15% of 1200 = Rs 180, so 1200 − 180 = Rs 1,020.', 'math-040', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A bus covers 300 km in 4 hours. At the same speed, how long for 450 km?', 'ایک بس 300 کلومیٹر 4 گھنٹے میں طے کرتی ہے۔ اسی رفتار سے 450 کلومیٹر کتنے گھنٹے میں طے کرے گی؟', '{"A":"5 hours","B":"6 hours","C":"7 hours","D":"5.5 hours"}', '6 hours', 'Speed = 300 ÷ 4 = 75 km/h, so 450 ÷ 75 = 6 hours.', 'math-041', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Ali and Hassan''s ages are in the ratio 5:3 and differ by 12 years. How old is Ali?', 'علی اور حسن کی عمروں کی نسبت 5:3 ہے اور فرق 12 سال ہے۔ علی کی عمر کیا ہے؟', '{"A":"18 years","B":"24 years","C":"30 years","D":"36 years"}', '30 years', '5 − 3 = 2 parts make 12 years, so Ali is 5 × 6 = 30.', 'math-042', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'How many prime numbers lie between 20 and 30?', '20 اور 30 کے درمیان کتنے اولی اعداد ہیں؟', '{"A":"1","B":"3","C":"4","D":"2"}', '2', 'Only 23 and 29 fall strictly between 20 and 30.', 'math-043', 'medium', 'intermediate', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A shop gives 20% off, then 10% off the reduced price. What single discount equals this?', 'ایک دکان پہلے 20 فیصد اور پھر گھٹی ہوئی قیمت پر 10 فیصد رعایت دیتی ہے۔ یہ کل کتنی رعایت کے برابر ہے؟', '{"A":"28%","B":"30%","C":"26%","D":"32%"}', '28%', 'After both cuts Rs 100 becomes 100 × 0.8 × 0.9 = Rs 72, a 28% fall.', 'math-044', 'hard', 'advanced', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Asim does a job in 10 days, Qasim in 15. Asim works 4 days then leaves. How long does Qasim need to finish?', 'عاصم ایک کام 10 دن میں اور قاسم 15 دن میں کرتا ہے۔ عاصم 4 دن کام کر کے چھوڑ دے تو قاسم باقی کام کتنے دن میں ختم کرے گا؟', '{"A":"6 days","B":"9 days","C":"11 days","D":"7.5 days"}', '9 days', 'Asim finishes 4/10 = 2/5, leaving 3/5, which takes Qasim 3/5 × 15 = 9 days.', 'math-045', 'hard', 'advanced', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A car drives to a city at 60 km/h and returns at 40 km/h. What is its average speed for the whole trip?', 'ایک کار جاتے ہوئے 60 اور آتے ہوئے 40 کلومیٹر فی گھنٹہ چلے تو پورے سفر کی اوسط رفتار کیا ہے؟', '{"A":"50 km/h","B":"45 km/h","C":"48 km/h","D":"52 km/h"}', '48 km/h', 'Average speed = 2 × 60 × 40 ÷ (60 + 40) = 48 km/h, not the simple mean 50.', 'math-046', 'hard', 'advanced', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Two numbers are in the ratio 4:5 and their LCM is 100. What is their sum?', 'دو اعداد کی نسبت 4:5 ہے اور ان کا ذواضعاف اقل 100 ہے۔ دونوں کا مجموعہ کیا ہے؟', '{"A":"40","B":"50","C":"35","D":"45"}', '45', 'Call them 4k and 5k: LCM = 20k = 100, so k = 5 and the sum is 20 + 25 = 45.', 'math-047', 'hard', 'advanced', 'ai_verified'),
  ('Arithmetic & Number Systems', '40 litres of mixture is 25% acid. After adding 10 litres of water, what percent is acid?', '40 لیٹر محلول میں 25 فیصد تیزاب ہے۔ 10 لیٹر پانی ملانے پر تیزاب کا فیصد کیا ہوگا؟', '{"A":"20%","B":"25%","C":"22.5%","D":"18%"}', '20%', 'The 10 litres of acid now sit in 50 litres: 10 × 100 ÷ 50 = 20%.', 'math-048', 'hard', 'advanced', 'ai_verified'),
  ('Arithmetic & Number Systems', 'Two brothers'' ages are in the ratio 4:3. In 6 years the ratio will be 5:4. How old is the younger now?', 'دو بھائیوں کی عمروں کی نسبت 4:3 ہے۔ 6 سال بعد نسبت 5:4 ہوگی۔ چھوٹے بھائی کی موجودہ عمر کیا ہے؟', '{"A":"15 years","B":"18 years","C":"21 years","D":"24 years"}', '18 years', 'Ages 4k and 3k become (4k+6)/(3k+6) = 5/4, giving k = 6, so the younger is 18.', 'math-049', 'hard', 'advanced', 'ai_verified'),
  ('Arithmetic & Number Systems', 'A trader buys an item for Rs 800, sells at 25% profit, and the buyer resells at 10% loss. What is the final price?', 'ایک دکاندار 800 روپے والی چیز 25 فیصد نفع پر بیچتا ہے، خریدار اسے 10 فیصد نقصان پر آگے بیچ دیتا ہے۔ آخری قیمت کیا ہے؟', '{"A":"Rs 880","B":"Rs 950","C":"Rs 900","D":"Rs 920"}', 'Rs 900', '800 × 1.25 = 1000, then 1000 × 0.9 = Rs 900.', 'math-050', 'hard', 'advanced', 'ai_verified')
) as v(chapter, question_en, question_ur, options, correct_text, explanation,
  source_ref, difficulty, level, review_status) on c.name = v.chapter
where b.title = 'Mathematics'
on conflict (content_hash) do nothing;

insert into public.mcq_subjects (mcq_id, subject_id)
select m.id, s.id from public.mcqs m cross join public.subjects s
where s.slug = 'mathematics' and m.source_ref = any (array['math-001', 'math-002', 'math-003', 'math-004', 'math-005', 'math-006', 'math-007', 'math-008', 'math-009', 'math-010', 'math-011', 'math-012', 'math-013', 'math-014', 'math-015', 'math-016', 'math-017', 'math-018', 'math-019', 'math-020', 'math-021', 'math-022', 'math-023', 'math-024', 'math-025', 'math-026', 'math-027', 'math-028', 'math-029', 'math-030', 'math-031', 'math-032', 'math-033', 'math-034', 'math-035', 'math-036', 'math-037', 'math-038', 'math-039', 'math-040', 'math-041', 'math-042', 'math-043', 'math-044', 'math-045', 'math-046', 'math-047', 'math-048', 'math-049', 'math-050'])
on conflict do nothing;

insert into public.mcq_exams (mcq_id, exam_id)
select m.id, e.id from public.mcqs m cross join public.exams e
where e.slug = any (array['forces', 'fpsc', 'nts-pts-ots', 'police', 'ppsc', 'spsc', 'teachers'])
  and m.source_ref = any (array['math-001', 'math-002', 'math-003', 'math-004', 'math-005', 'math-006', 'math-007', 'math-008', 'math-009', 'math-010', 'math-011', 'math-012', 'math-013', 'math-014', 'math-015', 'math-016', 'math-017', 'math-018', 'math-019', 'math-020', 'math-021', 'math-022', 'math-023', 'math-024', 'math-025'])
on conflict do nothing;

insert into public.mcq_exams (mcq_id, exam_id)
select m.id, e.id from public.mcqs m cross join public.exams e
where e.slug = any (array['css-pms', 'forces', 'fpsc', 'mdcat-ecat', 'nts-pts-ots', 'police', 'ppsc', 'spsc', 'teachers'])
  and m.source_ref = any (array['math-026', 'math-027', 'math-028', 'math-029', 'math-030', 'math-031', 'math-032', 'math-033', 'math-034', 'math-035', 'math-036', 'math-037', 'math-038', 'math-039', 'math-040', 'math-041', 'math-042', 'math-043', 'math-044', 'math-045', 'math-046', 'math-047', 'math-048', 'math-049', 'math-050'])
on conflict do nothing;

